            continue
        visited.add(curr)
        for p in preds.get(curr, []):
            stack.append(p)

def compute_es_ef(durs, preds):
    es = {}
    ef = {}
    # Topological sort or iterative
    computed = set()
    while len(computed) < len(durs):
        for t in durs:
            if t in computed: continue
            p_list = preds.get(t, [])
            if all(p in computed for p in p_list):
                start = max([ef[p] for p in p_list], default=0)
                es[t] = start
                ef[t] = start + durs[t]
                computed.add(t)
    return es, ef

es, ef = compute_es_ef(durs, preds)
project_duration = max(ef.values())

# backward pass
# lf = min(ls of successors), else project_duration
lf = {}
ls = {}
computed_b = set()
while len(computed_b) < len(durs):
    for t in durs:
        if t in computed_b: continue
        s_list = succs.get(t, [])
        if all(s in computed_b for s in s_list):
            finish = min([ls[s] for s in s_list], default=project_duration)
            lf[t] = finish
            ls[t] = finish - durs[t]
            computed_b.add(t)

